<?php
declare(strict_types=1);$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::sendSecurityHeaders($config);Security::startSession($config);
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}if(!Security::enforceAuthenticatedSession($config)||!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);exit('Session expired.');}
try{$db=Database::connection();$u=Authorization::user($db,(int)$_SESSION['user_id']);if(!$u)throw new RuntimeException('Authentication required.');$admin=$u['role_code']==='BARANGAY_ADMINISTRATOR'&&Authorization::can($db,$u,'dashboard.admin.view');$id=(int)($_POST['appointment_id']??0);if($id<1)throw new InvalidArgumentException('Invalid appointment.');$db->beginTransaction();$q=$db->prepare('SELECT user_id,status FROM appointment_requests WHERE appointment_id=:id FOR UPDATE');$q->execute(['id'=>$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new InvalidArgumentException('Appointment not found.');if(!$admin&&((int)$r['user_id']!==(int)$u['user_id']||$r['status']!=='SUBMITTED'))throw new RuntimeException('You may cancel only your own pending appointment.');if($r['status']==='CANCELLED')throw new InvalidArgumentException('Already cancelled.');$q=$db->prepare("UPDATE appointment_requests SET status='CANCELLED',reviewed_by_user_id=:uid,review_notes=:note,updated_at=NOW() WHERE appointment_id=:id");$q->execute(['uid'=>$u['user_id'],'note'=>$admin?'Cancelled by administrator.':'Cancelled by account holder while pending.','id'=>$id]);$q=$db->prepare("INSERT INTO appointment_status_history (appointment_id,old_status,new_status,notes,changed_by_user_id) VALUES (:id,:old,'CANCELLED',:note,:uid)");$q->execute(['id'=>$id,'old'=>$r['status'],'note'=>$admin?'Administrator cancellation':'User cancellation','uid'=>$u['user_id']]);AuditLogger::record($db,(int)$u['user_id'],$admin?'ADMIN_APPOINTMENT_CANCELLED':'USER_APPOINTMENT_CANCELLED','appointment',$id,['old_status'=>$r['status']]);$db->commit();header('Location: dashboard.php?updated=1');exit;}catch(Throwable $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();error_log('Cancel appointment: '.$e->getMessage());http_response_code(422);exit(Security::e($e->getMessage()));}
